#!/usr/bin/env node
/**
 * Regenerates the "which colour goes where" table in the design system doc
 * from design/tokens.json.
 *
 *   node design/gen-usage-table.mjs
 *
 * The table is written between the AUTOGENERATED markers in
 * docs/MovieMate-Design-System.md. Editing it by hand is pointless — the next
 * run overwrites it. Edit the `$usage` field in tokens.json instead.
 *
 * This exists so the answer to "which colour do I reach for here?" has exactly
 * one source, and so it cannot rot when a role is added.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, "..");

const tokens = JSON.parse(readFileSync(join(here, "tokens.json"), "utf8"));
const docPath = join(repo, "docs", "MovieMate-Design-System.md");

const START = "<!-- AUTOGENERATED:color-usage -->";
const END = "<!-- /AUTOGENERATED:color-usage -->";

const isToken = (node) =>
  node && typeof node === "object" && !Array.isArray(node) && "$value" in node;

function* walk(node, path = []) {
  if (!node || typeof node !== "object" || Array.isArray(node)) return;
  if (isToken(node)) {
    yield [path.join("."), node];
    return;
  }
  for (const [key, child] of Object.entries(node)) {
    if (key.startsWith("$")) continue;
    yield* walk(child, [...path, key]);
  }
}

function tokenAt(path) {
  let node = tokens;
  for (const segment of path.split(".")) {
    if (!node || typeof node !== "object") return undefined;
    node = node[segment];
  }
  return node;
}

function resolve(value) {
  if (typeof value !== "string") return value;
  const match = /^\{([^}]+)\}$/.exec(value.trim());
  if (!match) return value;
  const target = tokenAt(match[1]);
  return isToken(target) ? resolve(target.$value) : value;
}

/** Kotlin field name for a semantic role path, e.g. text.accent -> textAccent. */
function kotlinName(path) {
  const parts = path.split(".");
  // action.primary.fill -> actionPrimaryFill
  return parts
    .map((part, i) => (i === 0 ? part : part[0].toUpperCase() + part.slice(1)))
    .join("");
}

const GROUP_TITLES = {
  surface: "Surfaces — what a thing sits on",
  border: "Borders",
  text: "Text",
  action: "Actions — buttons and controls",
  status: "Status — what state something is in",
  partner: "Partner identity",
};

const rows = [];
for (const [path, token] of walk(tokens.sys.dark)) {
  if (token.$type !== "color") continue;
  rows.push({
    group: path.split(".")[0],
    path,
    kotlin: kotlinName(path),
    dark: resolve(token.$value),
    light: resolve(tokenAt(`sys.light.${path}`)?.$value),
    usage: token.$usage ?? "",
  });
}

const lines = [
  START,
  "",
  `<!-- Generated by design/gen-usage-table.mjs from design/tokens.json.`,
  `     Do not edit by hand — change the \`$usage\` field in tokens.json. -->`,
  "",
];

for (const [group, title] of Object.entries(GROUP_TITLES)) {
  const groupRows = rows.filter((r) => r.group === group);
  if (groupRows.length === 0) continue;

  lines.push(`#### ${title}`);
  lines.push("");
  lines.push("| Kotlin | Dark | Light | کجا استفاده می‌شود |");
  lines.push("|---|---|---|---|");
  for (const row of groupRows) {
    lines.push(
      `| \`colors.${row.kotlin}\` | \`${row.dark}\` | \`${row.light}\` | ${row.usage} |`
    );
  }
  lines.push("");
}

lines.push(END);

const doc = readFileSync(docPath, "utf8");
const startIndex = doc.indexOf(START);
const endIndex = doc.indexOf(END);

if (startIndex === -1 || endIndex === -1) {
  console.error(
    `Markers not found in ${docPath}.\nAdd these two lines where the table belongs:\n  ${START}\n  ${END}`
  );
  process.exit(1);
}

const updated =
  doc.slice(0, startIndex) + lines.join("\n") + doc.slice(endIndex + END.length);

writeFileSync(docPath, updated);
console.log(`Wrote ${rows.length} colour roles into ${docPath}`);
